-- Install into a NEW Neon database before importing current Windows data.
BEGIN;
CREATE SCHEMA IF NOT EXISTS dbo;
CREATE TABLE dbo.customers(customer_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,first_name varchar(50) NOT NULL,last_name varchar(50) NOT NULL,phone varchar(15) NOT NULL UNIQUE,created_at timestamp without time zone NOT NULL DEFAULT LOCALTIMESTAMP);
CREATE TABLE dbo.vehicles(vehicle_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,customer_id int NOT NULL REFERENCES dbo.customers(customer_id),license_plate varchar(20) NOT NULL UNIQUE,brand varchar(50) NOT NULL,model varchar(50) NOT NULL,color varchar(30) NOT NULL,vehicle_type varchar(30) NOT NULL);
CREATE TABLE dbo.member_cards(member_card_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,customer_id int NOT NULL REFERENCES dbo.customers(customer_id),card_number varchar(20) NOT NULL UNIQUE,member_type varchar(30) NOT NULL,remaining_credit int NOT NULL CHECK(remaining_credit>=0),expiry_date date NOT NULL,status varchar(20) NOT NULL CHECK(status IN('Active','Expired','Suspended')));
CREATE TABLE dbo.service_packages(package_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,package_name varchar(100) NOT NULL UNIQUE,price decimal(10,2) NOT NULL CHECK(price>0),duration_minutes int NOT NULL CHECK(duration_minutes BETWEEN 1 AND 600),status varchar(20) NOT NULL CHECK(status IN('Active','Inactive')));
CREATE TABLE dbo.wash_bays(bay_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,bay_name varchar(30) NOT NULL UNIQUE,status varchar(20) NOT NULL CHECK(status IN('Available','Occupied','Maintenance')));
CREATE TABLE dbo.staff(staff_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,first_name varchar(50) NOT NULL,last_name varchar(50) NOT NULL,phone varchar(15) NOT NULL,position varchar(20) NOT NULL CHECK(position IN('Technician','Detailer','Supervisor','Cashier')),status varchar(20) NOT NULL CHECK(status IN('Active','Inactive','On_Leave')));
CREATE TABLE dbo.bookings(booking_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,vehicle_id int NOT NULL REFERENCES dbo.vehicles(vehicle_id),package_id int NOT NULL REFERENCES dbo.service_packages(package_id),bay_id int NOT NULL REFERENCES dbo.wash_bays(bay_id),staff_id int NOT NULL REFERENCES dbo.staff(staff_id),member_card_id int NULL REFERENCES dbo.member_cards(member_card_id),start_time timestamp without time zone NOT NULL,end_time timestamp without time zone NOT NULL,booking_status varchar(20) NOT NULL CHECK(booking_status IN('Pending','In_Progress','Completed','Cancelled')),price_snapshot decimal(10,2) NOT NULL CHECK(price_snapshot>0),created_at timestamp without time zone NOT NULL DEFAULT LOCALTIMESTAMP,CHECK(start_time<end_time));
CREATE TABLE dbo.payments(payment_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,booking_id int NOT NULL REFERENCES dbo.bookings(booking_id),payment_date timestamp without time zone NOT NULL DEFAULT LOCALTIMESTAMP,amount decimal(10,2) NOT NULL CHECK(amount>0),payment_method varchar(20) NOT NULL CHECK(payment_method IN('Cash','PromptPay','Credit_Card','Member_Credit')));
CREATE TABLE dbo.materials(material_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,material_name varchar(100) NOT NULL UNIQUE,unit varchar(20) NOT NULL,unit_cost decimal(10,2) NOT NULL CHECK(unit_cost>=0),stock_qty decimal(10,2) NOT NULL CHECK(stock_qty>=0));
CREATE TABLE dbo.material_usage(usage_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,booking_id int NOT NULL REFERENCES dbo.bookings(booking_id),material_id int NOT NULL REFERENCES dbo.materials(material_id),quantity_used decimal(10,2) NOT NULL CHECK(quantity_used>0),unit_cost_snapshot decimal(10,2) NOT NULL CHECK(unit_cost_snapshot>=0));
CREATE INDEX ix_bookings_bay_time ON dbo.bookings(bay_id,start_time,end_time) INCLUDE(booking_status);
CREATE INDEX ix_bookings_staff_time ON dbo.bookings(staff_id,start_time,end_time) INCLUDE(booking_status);
CREATE INDEX ix_bookings_vehicle_time ON dbo.bookings(vehicle_id,start_time,end_time) INCLUDE(booking_status);
CREATE INDEX ix_payments_booking ON dbo.payments(booking_id) INCLUDE(amount,payment_method);
CREATE INDEX ix_usage_booking ON dbo.material_usage(booking_id) INCLUDE(quantity_used,unit_cost_snapshot);

-- PostgreSQL equivalents of the original SQL Server workflow.
CREATE OR REPLACE FUNCTION dbo.guard_booking() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 PERFORM pg_advisory_xact_lock(857210);
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Use cancellation, not deletion.'; END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.vehicle_id<>OLD.vehicle_id OR NEW.package_id<>OLD.package_id OR NEW.bay_id<>OLD.bay_id OR NEW.staff_id<>OLD.staff_id OR NEW.start_time<>OLD.start_time OR NEW.end_time<>OLD.end_time OR NEW.price_snapshot<>OLD.price_snapshot OR
   (NEW.member_card_id IS DISTINCT FROM OLD.member_card_id AND NOT(OLD.booking_status='Pending' AND NEW.booking_status='Pending' AND OLD.member_card_id IS NULL AND NEW.member_card_id IS NOT NULL))
   THEN RAISE EXCEPTION 'Booking details are immutable; cancel and recreate.'; END IF;
  IF NEW.booking_status<>OLD.booking_status AND NOT((OLD.booking_status='Pending' AND NEW.booking_status IN('In_Progress','Cancelled')) OR (OLD.booking_status='In_Progress' AND NEW.booking_status='Completed')) THEN RAISE EXCEPTION 'Invalid status transition.'; END IF;
 ELSE
  IF NEW.booking_status<>'Pending' THEN RAISE EXCEPTION 'New booking must be Pending.'; END IF;
 END IF;
 IF NEW.start_time::date<>NEW.end_time::date OR NEW.start_time::time<'08:00'::time OR NEW.end_time::time>'18:00'::time THEN RAISE EXCEPTION 'Business hours 08:00-18:00.'; END IF;
 IF NEW.booking_status IN('Pending','In_Progress') AND EXISTS(SELECT 1 FROM dbo.bookings b WHERE b.booking_id<>NEW.booking_id AND (b.bay_id=NEW.bay_id OR b.staff_id=NEW.staff_id OR b.vehicle_id=NEW.vehicle_id) AND b.start_time<NEW.end_time AND NEW.start_time<b.end_time AND b.booking_status IN('Pending','In_Progress')) THEN RAISE EXCEPTION 'Overlapping bay, staff or vehicle.'; END IF;
 IF TG_OP='UPDATE' AND OLD.booking_status='Pending' AND NEW.booking_status='In_Progress' AND NEW.member_card_id IS NOT NULL THEN
  UPDATE dbo.member_cards c SET remaining_credit=c.remaining_credit-1
  FROM dbo.vehicles v WHERE v.vehicle_id=NEW.vehicle_id AND c.member_card_id=NEW.member_card_id AND c.customer_id=v.customer_id AND c.status='Active' AND c.expiry_date>=NEW.start_time::date AND c.remaining_credit>0;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invalid member card or insufficient credits.'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER booking_guard BEFORE INSERT OR UPDATE OR DELETE ON dbo.bookings FOR EACH ROW EXECUTE FUNCTION dbo.guard_booking();
CREATE OR REPLACE FUNCTION dbo.deduct_material() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 PERFORM pg_advisory_xact_lock(857210);
 IF NOT EXISTS(SELECT 1 FROM dbo.bookings WHERE booking_id=NEW.booking_id AND booking_status='In_Progress') THEN RAISE EXCEPTION 'Materials require In_Progress booking.'; END IF;
 UPDATE dbo.materials SET stock_qty=stock_qty-NEW.quantity_used WHERE material_id=NEW.material_id AND stock_qty>=NEW.quantity_used;
 IF NOT FOUND THEN RAISE EXCEPTION 'Insufficient stock or invalid material.'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER material_stock BEFORE INSERT ON dbo.material_usage FOR EACH ROW EXECUTE FUNCTION dbo.deduct_material();

CREATE OR REPLACE FUNCTION dbo.usp_create_booking(p_vehicle_id int,p_package_id int,p_bay_id int,p_staff_id int,p_start_time timestamp,p_member_card_id int DEFAULT NULL)
RETURNS TABLE(booking_id int,end_time timestamp,price_snapshot numeric) LANGUAGE plpgsql AS $$
DECLARE price numeric; minutes int; finish timestamp;
BEGIN
 PERFORM pg_advisory_xact_lock(857210);
 SELECT p.price,p.duration_minutes INTO price,minutes FROM dbo.service_packages p WHERE package_id=p_package_id AND status='Active';
 IF price IS NULL OR p_start_time IS NULL THEN RAISE EXCEPTION 'Invalid package or time.'; END IF;
 finish=p_start_time+make_interval(mins=>minutes);
 IF NOT EXISTS(SELECT 1 FROM dbo.wash_bays WHERE bay_id=p_bay_id AND status='Available') THEN RAISE EXCEPTION 'Bay unavailable.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM dbo.staff WHERE staff_id=p_staff_id AND status='Active' AND position IN('Technician','Detailer')) THEN RAISE EXCEPTION 'Staff unavailable.'; END IF;
 IF p_member_card_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.member_cards c JOIN dbo.vehicles v ON v.customer_id=c.customer_id WHERE v.vehicle_id=p_vehicle_id AND c.member_card_id=p_member_card_id AND c.status='Active' AND c.expiry_date>=p_start_time::date AND c.remaining_credit>(SELECT COUNT(*) FROM dbo.bookings b WHERE b.member_card_id=c.member_card_id AND b.booking_status='Pending')) THEN RAISE EXCEPTION 'Card invalid or credits already reserved.'; END IF;
 RETURN QUERY INSERT INTO dbo.bookings AS b(vehicle_id,package_id,bay_id,staff_id,member_card_id,start_time,end_time,booking_status,price_snapshot) VALUES(p_vehicle_id,p_package_id,p_bay_id,p_staff_id,p_member_card_id,p_start_time,finish,'Pending',price) RETURNING b.booking_id,b.end_time,b.price_snapshot;
END $$;
CREATE OR REPLACE FUNCTION dbo.usp_start_booking(p_booking_id int) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
 PERFORM pg_advisory_xact_lock(857210);
 IF NOT EXISTS(SELECT 1 FROM dbo.bookings b JOIN dbo.wash_bays w ON w.bay_id=b.bay_id JOIN dbo.staff s ON s.staff_id=b.staff_id WHERE b.booking_id=p_booking_id AND b.booking_status='Pending' AND w.status='Available' AND s.status='Active') THEN RAISE EXCEPTION 'Booking cannot start.'; END IF;
 IF EXISTS(SELECT 1 FROM dbo.bookings b JOIN dbo.bookings x ON (b.bay_id=x.bay_id OR b.staff_id=x.staff_id OR b.vehicle_id=x.vehicle_id) WHERE b.booking_id=p_booking_id AND x.booking_status='In_Progress') THEN RAISE EXCEPTION 'Resource still working on another booking.'; END IF;
 UPDATE dbo.bookings SET booking_status='In_Progress' WHERE booking_id=p_booking_id;
END $$;
CREATE OR REPLACE FUNCTION dbo.usp_cancel_booking(p_booking_id int) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
 PERFORM pg_advisory_xact_lock(857210);
 UPDATE dbo.bookings SET booking_status='Cancelled' WHERE booking_id=p_booking_id AND booking_status='Pending';
 IF NOT FOUND THEN RAISE EXCEPTION 'Only Pending bookings may be cancelled.'; END IF;
END $$;
CREATE OR REPLACE FUNCTION dbo.usp_use_material(p_booking_id int,p_material_id int,p_quantity numeric) RETURNS void LANGUAGE plpgsql AS $$
DECLARE cost numeric;
BEGIN
 PERFORM pg_advisory_xact_lock(857210);
 SELECT unit_cost INTO cost FROM dbo.materials WHERE material_id=p_material_id;
 IF cost IS NULL OR p_quantity IS NULL OR p_quantity<=0 THEN RAISE EXCEPTION 'Invalid material or quantity.'; END IF;
 INSERT INTO dbo.material_usage(booking_id,material_id,quantity_used,unit_cost_snapshot) VALUES(p_booking_id,p_material_id,p_quantity,cost);
END $$;
CREATE OR REPLACE FUNCTION dbo.usp_complete_booking(p_booking_id int,p_payment_method varchar) RETURNS void LANGUAGE plpgsql AS $$
DECLARE price numeric; card int;
BEGIN
 PERFORM pg_advisory_xact_lock(857210);
 SELECT price_snapshot,member_card_id INTO price,card FROM dbo.bookings WHERE booking_id=p_booking_id AND booking_status='In_Progress';
 IF price IS NULL THEN RAISE EXCEPTION 'Only In_Progress bookings may complete.'; END IF;
 IF p_payment_method IS NULL OR(card IS NULL AND p_payment_method NOT IN('Cash','PromptPay','Credit_Card')) OR(card IS NOT NULL AND p_payment_method<>'Member_Credit') THEN RAISE EXCEPTION 'Payment method does not match booking.'; END IF;
 IF EXISTS(SELECT 1 FROM dbo.payments WHERE booking_id=p_booking_id) THEN
  IF (SELECT COUNT(*) FROM dbo.payments WHERE booking_id=p_booking_id)<>1 OR NOT EXISTS(SELECT 1 FROM dbo.payments WHERE booking_id=p_booking_id AND amount=price AND payment_method=p_payment_method) THEN RAISE EXCEPTION 'Existing payment does not match; review before completion.'; END IF;
 ELSE
  INSERT INTO dbo.payments(booking_id,amount,payment_method) VALUES(p_booking_id,price,p_payment_method);
 END IF;
 UPDATE dbo.bookings SET booking_status='Completed' WHERE booking_id=p_booking_id;
END $$;
CREATE OR REPLACE FUNCTION dbo.sp_process_car_wash_booking(p_vehicle_id int,p_package_id int,p_bay_id int,p_staff_id int,p_start_time timestamp,p_payment_method varchar,p_member_card_id int DEFAULT NULL,p_paid_amount numeric DEFAULT NULL)
RETURNS TABLE(booking_id int,end_time timestamp,price_snapshot numeric,booking_status varchar,payment_method varchar) LANGUAGE plpgsql AS $$
DECLARE b record;
BEGIN
 PERFORM pg_advisory_xact_lock(857210);
 SELECT * INTO b FROM dbo.usp_create_booking(p_vehicle_id,p_package_id,p_bay_id,p_staff_id,p_start_time,p_member_card_id);
 IF p_payment_method IS NULL OR(p_member_card_id IS NULL AND p_payment_method NOT IN('Cash','PromptPay','Credit_Card')) OR(p_member_card_id IS NOT NULL AND p_payment_method<>'Member_Credit') THEN RAISE EXCEPTION 'Payment method does not match member card.'; END IF;
 IF p_member_card_id IS NULL AND (p_paid_amount IS NULL OR p_paid_amount<>b.price_snapshot) THEN RAISE EXCEPTION 'Cash/transfer/card amount must equal service price.'; END IF;
 IF p_member_card_id IS NOT NULL AND COALESCE(p_paid_amount,0)<>0 THEN RAISE EXCEPTION 'Member redemption must not include new cash.'; END IF;
 PERFORM dbo.usp_start_booking(b.booking_id);
 INSERT INTO dbo.payments(booking_id,amount,payment_method) VALUES(b.booking_id,b.price_snapshot,p_payment_method);
 RETURN QUERY SELECT b.booking_id,b.end_time,b.price_snapshot,'In_Progress'::varchar,p_payment_method;
END $$;
CREATE OR REPLACE FUNCTION dbo.usp_save_customer(p_first_name varchar,p_last_name varchar,p_phone varchar,p_customer_id int DEFAULT NULL)
RETURNS TABLE(customer_id int) LANGUAGE plpgsql AS $$
DECLARE new_id int;
BEGIN
 PERFORM pg_advisory_xact_lock(857210);
 IF NULLIF(trim(p_first_name),'') IS NULL OR NULLIF(trim(p_last_name),'') IS NULL OR NULLIF(trim(p_phone),'') IS NULL THEN RAISE EXCEPTION 'Required customer fields.'; END IF;
 IF p_customer_id IS NULL THEN
  INSERT INTO dbo.customers AS c(first_name,last_name,phone) VALUES(p_first_name,p_last_name,p_phone) RETURNING c.customer_id INTO new_id;
 ELSE
  UPDATE dbo.customers c SET first_name=p_first_name,last_name=p_last_name,phone=p_phone WHERE c.customer_id=p_customer_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Customer not found.'; END IF;
  new_id=p_customer_id;
 END IF;
 RETURN QUERY SELECT new_id;
END $$;
CREATE OR REPLACE FUNCTION dbo.usp_delete_customer(p_customer_id int) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
 PERFORM pg_advisory_xact_lock(857210);
 DELETE FROM dbo.customers WHERE customer_id=p_customer_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Customer not found.'; END IF;
END $$;
CREATE OR REPLACE FUNCTION dbo.usp_save_vehicle(p_customer_id int,p_license_plate varchar,p_brand varchar,p_model varchar,p_color varchar,p_vehicle_type varchar,p_vehicle_id int DEFAULT NULL)
RETURNS TABLE(vehicle_id int) LANGUAGE plpgsql AS $$
DECLARE new_id int;
BEGIN
 PERFORM pg_advisory_xact_lock(857210);
 IF p_vehicle_id IS NULL THEN
  INSERT INTO dbo.vehicles AS v(customer_id,license_plate,brand,model,color,vehicle_type) VALUES(p_customer_id,p_license_plate,p_brand,p_model,p_color,p_vehicle_type) RETURNING v.vehicle_id INTO new_id;
 ELSE
  IF EXISTS(SELECT 1 FROM dbo.bookings b WHERE b.vehicle_id=p_vehicle_id) THEN RAISE EXCEPTION 'Vehicle with booking history is immutable in this version.'; END IF;
  UPDATE dbo.vehicles v SET customer_id=p_customer_id,license_plate=p_license_plate,brand=p_brand,model=p_model,color=p_color,vehicle_type=p_vehicle_type WHERE v.vehicle_id=p_vehicle_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Vehicle not found.'; END IF;
  new_id=p_vehicle_id;
 END IF;
 RETURN QUERY SELECT new_id;
END $$;
CREATE OR REPLACE FUNCTION dbo.usp_delete_vehicle(p_vehicle_id int) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
 PERFORM pg_advisory_xact_lock(857210);
 DELETE FROM dbo.vehicles WHERE vehicle_id=p_vehicle_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Vehicle not found.'; END IF;
END $$;
CREATE VIEW dbo.vw_daily_car_wash_revenue_summary AS
WITH receipts AS(SELECT booking_id,SUM(CASE WHEN payment_method='Member_Credit' THEN 0 ELSE amount END) cash_received,SUM(CASE WHEN payment_method='Member_Credit' THEN amount ELSE 0 END) member_value FROM dbo.payments GROUP BY booking_id)
SELECT b.start_time::date service_date,b.package_id,p.package_name,b.bay_id,w.bay_name,COUNT(*) completed_cars,SUM(b.price_snapshot) service_value,SUM(COALESCE(r.cash_received,0)) cash_received,SUM(COALESCE(r.member_value,0)) member_redemption_value
FROM dbo.bookings b JOIN dbo.service_packages p ON p.package_id=b.package_id JOIN dbo.wash_bays w ON w.bay_id=b.bay_id LEFT JOIN receipts r ON r.booking_id=b.booking_id WHERE b.booking_status='Completed'
GROUP BY b.start_time::date,b.package_id,p.package_name,b.bay_id,w.bay_name;

COMMIT;
